let state=structuredClone(seed),category='Semua',search='',menuMgmtSearchQuery='',sessionLocked=true,reportFrom='',reportTo='',reportPayment='all',reportCashier='all',reportMonth=businessDate().slice(0,7),availablePrinters=[];
