const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n),t=k=>I18N[state.language][k]||EXTRA_I18N[state.language][k]||k,esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function hashPin(pin){const bytes=new TextEncoder().encode(String(pin)),hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')}

function cartKey(type=state.orderType,table=state.table){return type==='dineIn'?`table:${table}`:'takeaway'}
function currentCart(){const key=cartKey();if(!state.carts[key])state.carts[key]=[];return state.carts[key]}
function replaceCurrentCart(cart){state.carts[cartKey()]=cart}
function tableCart(table){return state.carts[`table:${table}`]||[]}
function currentSplitBills(key=cartKey()){if(!state.splitBills[key])state.splitBills[key]=[];return state.splitBills[key]}
function tableSplitBills(table){return state.splitBills[`table:${table}`]||[]}
function allOpenItems(key=cartKey()){return [...(state.carts[key]||[]),...(state.splitBills[key]||[]).flatMap(b=>b.items)]}
function mergeItem(cart,item,qty=item.qty){const found=cart.find(x=>x.id===item.id);if(found){found.qty+=qty;if(item.itemDiscount&&!found.itemDiscount)found.itemDiscount=item.itemDiscount;}else cart.push({...item,qty})}
function transferTable(sourceTable,targetTable){if(!sourceTable||!targetTable||sourceTable===targetTable)return;const sKey=`table:${sourceTable}`,tKey=`table:${targetTable}`,sItems=allOpenItems(sKey);if(!sItems.length){toast(state.language==='en'?'No active orders on this table.':'Tidak ada pesanan aktif di meja ini.');return}state.carts[tKey]||=[];state.splitBills[tKey]||=[];(state.carts[sKey]||[]).forEach(i=>mergeItem(state.carts[tKey],i));state.splitBills[tKey].push(...(state.splitBills[sKey]||[]));if(!state.orderIds[tKey]&&state.orderIds[sKey])state.orderIds[tKey]=state.orderIds[sKey];if(!state.orderMeta[tKey]&&state.orderMeta[sKey])state.orderMeta[tKey]=state.orderMeta[sKey];if(state.splitPersonCounters[sKey])state.splitPersonCounters[tKey]=Math.max(state.splitPersonCounters[tKey]||1,state.splitPersonCounters[sKey]);delete state.carts[sKey];delete state.splitBills[sKey];delete state.splitPersonCounters[sKey];delete state.orderIds[sKey];delete state.orderMeta[sKey];state.tickets.forEach(t=>{if(t.table===sourceTable)t.table=targetTable});if(state.orderType==='dineIn'&&state.table===sourceTable)state.table=targetTable;save();closeModal();render();toast(state.language==='en'?`Order transferred from Table ${sourceTable} to ${targetTable}.`:`Pesanan berhasil dipindahkan dari Meja ${sourceTable} ke Meja ${targetTable}.`);}
function reservedQuantity(productId){return Object.values(state.carts).flat().filter(i=>i.id===productId).reduce((s,i)=>s+i.qty,0)+Object.values(state.splitBills).flat().flatMap(b=>b.items).filter(i=>i.id===productId).reduce((s,i)=>s+i.qty,0)}
function businessDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function nextDocumentId(prefix,counterName){const number=state[counterName]++;return `${prefix}-${businessDate().replaceAll('-','')}-${String(number).padStart(4,'0')}`}
function ensureOrderId(key=cartKey()){if(!state.orderIds[key])state.orderIds[key]=nextDocumentId('ORD','nextOrderNumber');return state.orderIds[key]}
async function load(){const saved=window.desktop?await window.desktop.load():JSON.parse(localStorage.getItem('anda-pos')||'null');if(saved){state={...state,...saved};state.settings={...seed.settings,...(saved.settings||{})};state.carts=state.carts||{};state.splitBills=state.splitBills||{};state.splitPersonCounters=state.splitPersonCounters||{};state.orderIds=state.orderIds||{};state.orderMeta=state.orderMeta||{};state.nextOrderNumber=state.nextOrderNumber||1;state.nextInvoiceNumber=state.nextInvoiceNumber||1;state.nextSplitBillNumber=state.nextSplitBillNumber||1;state.categories=state.categories||[...new Set(state.products.map(p=>p.category))];state.users=state.users||structuredClone(seed.users);state.products.forEach(p=>{if(p.taxable===undefined)p.taxable=true;if(p.unlimitedStock===undefined)p.unlimitedStock=false});Object.values(state.carts).forEach(cart=>cart.forEach(p=>{if(p.taxable===undefined)p.taxable=true;if(p.unlimitedStock===undefined)p.unlimitedStock=false}));Object.values(state.splitBills).flat().forEach(b=>b.items.forEach(p=>{if(p.taxable===undefined)p.taxable=true;if(p.unlimitedStock===undefined)p.unlimitedStock=false}));if(!state.user.id){const match=state.users.find(u=>u.role===state.user.role);state.user={id:match.id,name:match.name,role:match.role}}if(Array.isArray(saved.cart)&&saved.cart.length&&!state.carts[cartKey()])state.carts[cartKey()]=saved.cart;delete state.cart}state.shiftHistory=Array.isArray(state.shiftHistory)?state.shiftHistory:[];state.nextShiftNumber=Number(state.nextShiftNumber)||1;if(!state.shift||typeof state.shift!=='object'||(state.shift.open&&!state.shift.id))state.shift={open:false};const keys=new Set([...Object.keys(state.carts),...Object.keys(state.splitBills)]);for(const key of keys)if(allOpenItems(key).length&&!state.orderIds[key])ensureOrderId(key);render();showUsers(true);}
async function save(){if(window.desktop)await window.desktop.save(state);else localStorage.setItem('anda-pos',JSON.stringify(state));}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
const names={pos:'pos',tables:'tables',kitchen:'kitchen',inventory:'inventory',menuManagement:'menuManagement',tableManagement:'tableManagement',users:'users',reports:'reports',shift:'shift',settings:'settings'};
const icons={pos:'⌘',tables:'▦',kitchen:'♨',inventory:'▤',menuManagement:'☷',tableManagement:'▦+',users:'♙',reports:'↗',shift:'◷',settings:'⚙'};
function renderNav(){let allowed=state.user.role==='cashier'?['pos','tables','kitchen','shift']:state.user.role==='admin'?['pos','tables','kitchen','inventory','menuManagement','tableManagement','reports','shift','settings']:Object.keys(names);if(!state.settings.kitchenEnabled)allowed=allowed.filter(k=>k!=='kitchen');$('#nav').innerHTML=allowed.map(k=>`<button class="nav-btn ${state.activeView===k?'active':''}" data-view="${k}"><i>${icons[k]}</i><span>${t(names[k])}</span></button>`).join('');}
function render(){document.documentElement.lang=state.language;document.title=`${state.settings.restaurantName} · POS`;document.body.dataset.view=state.activeView;renderNav();document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));$('#langBtn').textContent=state.language==='id'?'EN':'ID';$('#date').textContent=new Intl.DateTimeFormat(state.language==='id'?'id-ID':'en-US',{weekday:'long',day:'numeric',month:'long'}).format(new Date());$('#pageTitle').textContent=t(names[state.activeView]);$('#shiftName').textContent=state.shift.open?`${state.shift.name} · ${state.shift.cashierName||state.user.name}`:t('startShift');$('#shiftTime').textContent=state.shift.open?`${clockTime(state.shift.openedAt)} — sekarang`:'Tidak aktif';$('#userBtn').textContent=state.user.role==='owner'?'OW':state.user.role==='admin'?'AD':'KS';const restaurant=state.settings.restaurantName||'Restoran',parts=restaurant.split(/\s+/),logo=$('#brandLogo'),mark=$('#brandMark');$('#brandName').textContent=(parts[0]||'POS').toUpperCase();$('#brandSubtitle').textContent=parts.slice(1).join(' ')||'Restaurant POS';if(state.settings.brandLogo){logo.src=state.settings.brandLogo;logo.classList.remove('hidden');mark.classList.add('hidden')}else{logo.classList.add('hidden');mark.classList.remove('hidden');mark.textContent=(restaurant[0]||'R').toUpperCase()}renderView();renderOrder();}

function decorateOrderPanel(){const head=$('#orderPanel .order-head'),meta=state.orderMeta[cartKey()];if(!head)return;if(meta?.waiter&&!head.querySelector('.order-waiter')){const label=document.createElement('small');label.className='order-waiter';label.textContent=`Waiter · ${meta.waiter}`;head.firstElementChild.appendChild(label)}if(!head.querySelector('#collapseCart')){const collapse=document.createElement('button');collapse.className='icon-btn collapse-cart';collapse.id='collapseCart';collapse.title='Tutup keranjang';collapse.textContent='›';head.insertBefore(collapse,head.lastElementChild)}}
function renderView(){
  const f={pos:renderPOS,tables:renderTables,kitchen:renderKitchen,inventory:renderInventory,menuManagement:renderMenuManagement,tableManagement:renderTableManagement,users:renderUsers,reports:renderReports,shift:renderShift,settings:renderSettings};
  const prevChips = $('.chips');
  const prevScroll = prevChips ? prevChips.scrollLeft : null;
  $('#view').innerHTML=f[state.activeView]();
  if(state.activeView==='settings')mountReceiptFontSetting();
  if(prevScroll !== null){
    const nextChips = $('.chips');
    if(nextChips) nextChips.scrollLeft = prevScroll;
  }
  bindView();
}

function selectPOSCategory(catName){
  category=catName;
  search='';
  const s=$('#search');
  if(s)s.value='';
  document.querySelectorAll('.chips .chip').forEach(btn=>{
    btn.classList.toggle('active',btn.dataset.cat===catName);
  });
  const grid=$('.product-grid');
  if(grid){
    const products=state.products.filter(p=>p.active!==false&&(category==='Semua'||p.category===category));
    grid.innerHTML=products.map(p=>`<button class="product" data-product="${p.id}"><span class="product-icon">${esc(p.icon)}</span><strong>${esc(state.language==='id'?p.name:p.en)}</strong><small>${money(p.price)}</small><span class="stock">${p.unlimitedStock?'∞ Unlimited':`${p.stock} ${t('stock')}`}</span></button>`).join('');
    grid.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>add(+b.dataset.product));
  } else {
    renderView();
  }
}

function renderPOS(){
  const cats=['Semua',...state.categories];
  if(category!=='Semua'&&!state.categories.includes(category))category='Semua';
  const q=search.trim().toLowerCase();
  const products=state.products.filter(p=>{
    if(p.active===false)return false;
    if(q){
      const matchName=(p.name||'').toLowerCase().includes(q);
      const matchEn=(p.en||'').toLowerCase().includes(q);
      const matchCat=(p.category||'').toLowerCase().includes(q);
      const matchPrice=String(p.price||'').includes(q);
      return matchName||matchEn||matchCat||matchPrice;
    }
    return category==='Semua'||p.category===category;
  });
  return `<div class="toolbar"><input class="search" id="search" value="${esc(search)}" placeholder="${t('search')}"></div><div class="chips">${cats.map(c=>`<button class="chip ${category===c?'active':''}" data-cat="${esc(c)}">${c==='Semua'?t('all'):esc(c)}</button>`).join('')}</div><br><div class="product-grid">${products.map(p=>`<button class="product" data-product="${p.id}"><span class="product-icon">${esc(p.icon)}</span><strong>${esc(state.language==='id'?p.name:p.en)}</strong><small>${money(p.price)}</small><span class="stock">${p.unlimitedStock?'∞ Unlimited':`${p.stock} ${t('stock')}`}</span></button>`).join('')}</div>`
}


function renderTables(){const available=state.tables.filter(x=>!allOpenItems(`table:${x.id}`).length).length;return `<div class="section-title"><h2>Area restoran</h2><span>${available} ${t('available')}</span></div><div class="table-grid">${state.tables.map(x=>{const key=`table:${x.id}`,items=allOpenItems(key),bills=tableSplitBills(x.id),status=items.length?'occupied':'available',sum=totals(items);return `<button class="table-card ${status}" data-table="${x.id}"><strong>${x.id}</strong><span>${x.seats} kursi · ${t(status)}${items.length?` · ${items.reduce((s,i)=>s+i.qty,0)} item${bills.length?` · ${bills.length} bill tersimpan`:''}<br>${esc(state.orderIds[key]||'')}<br>${money(sum.total)}`:''}</span></button>`}).join('')}</div>`}
function renderKitchen(){return `<div class="section-title"><h2>Ticket rail</h2><span>${state.tickets.length} pesanan aktif</span></div><div class="kitchen">${state.tickets.map(x=>`<article class="ticket ${x.status}"><small>${x.time} · ${x.id}</small><h3>${x.table}</h3><ul>${x.items.map(i=>`<li>${i}</li>`).join('')}</ul><button class="secondary finish-ticket" data-ticket="${x.id}">${x.status==='ready'?t('finish'):t('ready')}</button></article>`).join('')||'<div class="panel">Belum ada pesanan aktif.</div>'}</div>`}
function renderInventory(){return `<div class="section-title"><h2>Bahan & menu</h2><span>${state.products.filter(p=>!p.unlimitedStock&&p.stock<10).length} ${t('lowStock')}</span></div><table class="inventory-table"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th></tr></thead><tbody>${state.products.map(p=>`<tr><td>${esc(p.icon)} ${esc(p.name)}</td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td class="${!p.unlimitedStock&&p.stock<10?'low':''}">${p.unlimitedStock?'<span class="status-pill">∞ Unlimited</span>':p.stock}</td></tr>`).join('')}</tbody></table>`}
function renderMenuManagement(){
  const query = menuMgmtSearchQuery.trim().toLowerCase();
  const filteredProducts = state.products.filter(p => {
    if (!query) return true;
    const matchName = (p.name || '').toLowerCase().includes(query);
    const matchEn = (p.en || '').toLowerCase().includes(query);
    const matchCat = (p.category || '').toLowerCase().includes(query);
    const matchPrice = String(p.price || '').includes(query);
    return matchName || matchEn || matchCat || matchPrice;
  });
  const english = state.language === 'en';
  return `<div class="section-title"><div><h2>${english ? 'Menu Catalogue' : 'Kategori menu'}</h2><p class="muted">${english ? 'Organize items, tax, and stock rules.' : 'Susun menu, pajak, dan aturan stok per item.'}</p></div><div class="action-row"><button class="secondary" id="addCategory">${english ? '+ Category' : '+ Kategori'}</button><button class="primary" id="addProduct">${english ? '+ Item' : '+ Menu'}</button></div></div><div class="category-admin">${state.categories.map(c=>`<div class="category-admin-card"><div><strong>${esc(c)}</strong><small>${state.products.filter(p=>p.category===c).length} ${english ? 'items' : 'menu'}</small></div><div><button class="mini edit-category" data-category="${esc(c)}">${english ? 'Edit' : 'Edit'}</button><button class="mini danger-text delete-category" data-category="${esc(c)}">${english ? 'Delete' : 'Hapus'}</button></div></div>`).join('')}</div><br><div class="menu-mgmt-toolbar"><label class="field menu-mgmt-search-field"><span>${english ? 'Search menu' : 'Cari menu'}</span><input class="search" id="menuMgmtSearch" value="${esc(menuMgmtSearchQuery)}" placeholder="${english ? 'Search menu name, category, or price…' : 'Cari nama menu, kategori, atau harga…'}" autocomplete="off"></label>${menuMgmtSearchQuery ? `<span class="menu-search-count">${filteredProducts.length} ${english ? 'items found' : 'menu ditemukan'}</span>` : ''}</div><table class="inventory-table"><thead><tr><th>${english ? 'Item' : 'Menu'}</th><th>${english ? 'Category' : 'Kategori'}</th><th>${english ? 'Price' : 'Harga'}</th><th>${english ? 'Tax' : 'Pajak'}</th><th>${english ? 'Stock' : 'Stok'}</th><th>${english ? 'Status' : 'Status'}</th><th></th></tr></thead><tbody>${filteredProducts.map(p=>`<tr><td>${esc(p.icon)} <strong>${esc(p.name)}</strong><br><small>${esc(p.en)}</small></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td><span class="status-pill ${p.taxable===false?'inactive':''}">${p.taxable===false?'Tanpa pajak':'Tax 10%'}</span></td><td>${p.unlimitedStock?'<span class="status-pill">∞ Unlimited</span>':p.stock}</td><td><span class="status-pill ${p.active===false?'inactive':''}">${p.active===false?'Nonaktif':'Aktif'}</span></td><td><button class="mini edit-product" data-id="${p.id}">Edit</button><button class="mini danger-text delete-product" data-id="${p.id}">Hapus</button></td></tr>`).join('') || `<tr><td colspan="7" class="empty-cell">${english ? 'No matching menu items.' : 'Tidak ada menu yang sesuai dengan pencarian.'}</td></tr>`}</tbody></table>`;
}
function renderUsers(){return `<div class="section-title"><div><h2>Pengguna & PIN</h2><p class="muted">Akses disesuaikan dengan peran setiap pengguna.</p></div><button class="primary" id="addUser">+ Pengguna</button></div><div class="cards user-summary"><div class="stat"><small>Owner</small><strong>${state.users.filter(u=>u.role==='owner'&&u.active).length}</strong></div><div class="stat"><small>Admin</small><strong>${state.users.filter(u=>u.role==='admin'&&u.active).length}</strong></div><div class="stat"><small>Kasir</small><strong>${state.users.filter(u=>u.role==='cashier'&&u.active).length}</strong></div></div><br><table class="inventory-table"><thead><tr><th>Nama</th><th>Peran</th><th>Status</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong>${u.id===state.user.id?' <span class="status-pill">Aktif saat ini</span>':''}</td><td>${roleLabel(u.role)}</td><td>${u.active?'Aktif':'Nonaktif'}</td><td><button class="mini edit-user" data-id="${u.id}">Edit / PIN</button>${u.id!==state.user.id?`<button class="mini toggle-user" data-id="${u.id}">${u.active?'Nonaktifkan':'Aktifkan'}</button>`:''}</td></tr>`).join('')}</tbody></table>`}
function renderTableManagement(){return `<div class="section-title"><div><h2>Manajemen meja</h2><p class="muted">Tambah meja, atur kapasitas, atau hapus meja kosong.</p></div><button class="primary" id="addTable">+ Tambah meja</button></div><div class="table-admin-grid">${state.tables.map(table=>{const open=allOpenItems(`table:${table.id}`),sum=totals(open);return `<article class="table-admin-card ${open.length?'busy':''}"><div><strong>${esc(table.id)}</strong><span>${table.seats} kursi</span></div><p>${open.length?`${open.reduce((s,i)=>s+i.qty,0)} item · ${money(sum.total)}`:'Tidak ada pesanan'}</p><div><button class="mini edit-table" data-table-edit="${esc(table.id)}">Ubah kursi</button><button class="mini danger-text delete-table" data-table-delete="${esc(table.id)}" ${open.length?'disabled':''}>Hapus</button></div></article>`}).join('')}</div>`}
function renderSettings(){const printerOptions=[...(state.settings.printerName&&!availablePrinters.some(p=>p.name===state.settings.printerName)?[{name:state.settings.printerName,displayName:state.settings.printerName}]:[]),...availablePrinters];return `<div class="section-title"><div><h2>Pengaturan aplikasi</h2><p class="muted">Identitas restoran, alur operasional, printer, dan keamanan data.</p></div></div><form id="settingsForm" class="settings-grid"><section class="setting-panel branding-panel"><div class="setting-icon">◆</div><div><h3>Identitas restoran</h3><p>Nama dan logo akan tampil di aplikasi serta struk.</p><label class="field"><span>Nama restoran</span><input name="restaurantName" value="${esc(state.settings.restaurantName)}" required maxlength="80"></label><div class="logo-editor"><div class="logo-preview">${state.settings.brandLogo?`<img src="${state.settings.brandLogo}" alt="Logo saat ini">`:`<span>${esc((state.settings.restaurantName||'R')[0].toUpperCase())}</span>`}</div><div><label class="secondary file-button" for="logoInput">Upload logo</label><input class="hidden" id="logoInput" type="file" accept="image/png,image/jpeg,image/webp">${state.settings.brandLogo?'<button type="button" class="mini danger-text" id="removeLogo">Hapus logo</button>':''}<small>PNG, JPG, atau WebP. Maksimal 2 MB.</small></div></div></div></section><section class="setting-panel"><div class="setting-icon">♨</div><div><h3>Pesanan dapur</h3><p>Matikan jika restoran tidak menggunakan layar atau tiket dapur.</p><label class="switch-row"><input name="kitchenEnabled" type="checkbox" ${state.settings.kitchenEnabled?'checked':''}><span>Aktifkan fitur dapur</span></label></div></section><section class="setting-panel"><div class="setting-icon">▤</div><div><h3>Thermal printer 80 mm</h3><p>Cetak langsung memakai teks native ESC/POS agar tajam dan tidak terpotong oleh skala driver Windows.</p><label class="field"><span>Mesin cetak langsung</span><select name="directPrintMode"><option value="escpos" ${state.settings.directPrintMode!=='graphics'?'selected':''}>Teks native ESC/POS · Direkomendasikan</option><option value="graphics" ${state.settings.directPrintMode==='graphics'?'selected':''}>Grafis Windows · Kompatibilitas</option></select></label><label class="field"><span>Lebar teks native</span><select name="directPrintColumns"><option value="42" ${Number(state.settings.directPrintColumns)!==48?'selected':''}>42 karakter · Aman (direkomendasikan)</option><option value="48" ${Number(state.settings.directPrintColumns)===48?'selected':''}>48 karakter · Printer 576-dot</option></select></label><label class="field"><span>Area konten mode grafis</span><select name="receiptContentWidth"><option value="64" ${Number(state.settings.receiptContentWidth)===64?'selected':''}>64 mm · Aman (direkomendasikan)</option><option value="68" ${Number(state.settings.receiptContentWidth)===68?'selected':''}>68 mm · Sedang</option><option value="72" ${Number(state.settings.receiptContentWidth)===72?'selected':''}>72 mm · Lebar penuh</option></select></label><label class="field"><span>Printer default</span><select name="printerName"><option value="">Pilih melalui dialog setiap mencetak</option>${printerOptions.map(p=>`<option value="${esc(p.name)}" ${state.settings.printerName===p.name?'selected':''}>${esc(p.displayName||p.name)}</option>`).join('')}</select></label><div class="data-actions"><button type="button" class="secondary" id="detectPrinters">Deteksi printer</button><button type="button" class="secondary" id="testReceipt">Cetak struk uji</button></div><label class="switch-row"><input name="silentPrint" type="checkbox" ${state.settings.silentPrint?'checked':''} ${state.settings.printerName?'':'disabled'}><span>Cetak langsung tanpa dialog</span></label><label class="switch-row"><input name="autoCut" type="checkbox" ${state.settings.autoCut!==false?'checked':''}><span>Potong kertas otomatis setelah cetak langsung</span></label><small>ESC/POS mengirim huruf langsung ke printer. Jika printer bukan ESC/POS, pilih mode Grafis Windows.</small></div></section><section class="setting-panel data-panel"><div class="setting-icon">↕</div><div><h3>Backup & restore database</h3><p>Backup mencakup menu, transaksi, pengguna, meja, pengaturan, nama restoran, dan logo.</p><div class="data-actions"><button type="button" class="secondary" id="backupDatabase">Buat backup</button><button type="button" class="danger" id="restoreDatabase">Restore backup</button></div><small>Restore akan mengganti seluruh data yang sedang digunakan.</small></div></section><div class="settings-actions"><button class="primary">Simpan pengaturan</button></div></form>`}
function mountReceiptFontSetting(){const printer=$('#settingsForm [name="printerName"]')?.closest('.field');if(!printer)return;const field=document.createElement('label');field.className='field';field.innerHTML=`<span>Gaya font struk</span><select name="receiptFontStyle"><option value="clear">Tipis & jelas · Monospace</option><option value="medium">Sedang · Sans serif</option><option value="bold">Tebal · Sans serif</option></select>`;field.querySelector('select').value=state.settings.receiptFontStyle||'clear';printer.before(field);const autoCut=$('#settingsForm [name="autoCut"]')?.closest('.switch-row');if(autoCut){const feed=document.createElement('label');feed.className='field';feed.innerHTML=`<span>Jarak sebelum potong</span><select name="cutFeedLines"><option value="6">6 baris · Pendek</option><option value="8">8 baris · Aman</option><option value="10">10 baris · Ekstra aman</option></select>`;feed.querySelector('select').value=String([6,8,10].includes(Number(state.settings.cutFeedLines))?Number(state.settings.cutFeedLines):8);autoCut.before(feed)}}
function monthlyRevenueData(month=reportMonth){const [year,monthNumber]=month.split('-').map(Number),days=new Date(year,monthNumber,0).getDate(),values=Array(days).fill(0);state.transactions.filter(x=>{const date=x.date||x.timestamp?.slice(0,10)||'';return date.startsWith(`${month}-`)&&(reportPayment==='all'||paymentMatches(x,reportPayment))&&(reportCashier==='all'||String(x.cashierId)===reportCashier)}).forEach(x=>{const date=x.date||x.timestamp.slice(0,10),day=Number(date.slice(8,10));if(day>=1&&day<=days)values[day-1]+=(Number(x.subtotal)||0)-(Number(x.discountAmount)||0)});return{values,total:values.reduce((a,b)=>a+b,0),max:Math.max(0,...values)}}
function mountMonthlyRevenueChart(){const anchor=$('.report-filters');if(!anchor)return;const data=monthlyRevenueData(),locale=state.language==='id'?'id-ID':'en-US',label=new Intl.DateTimeFormat(locale,{month:'long',year:'numeric'}).format(new Date(`${reportMonth}-01T12:00:00`)),section=document.createElement('section');section.className='revenue-chart panel';section.innerHTML=`<div class="chart-heading"><div><small>PENDAPATAN HARIAN</small><h3>${esc(label)}</h3></div><label>Bulan<input id="reportMonth" type="month" value="${reportMonth}"></label><strong>${money(data.total)}</strong></div><div class="bar-chart" role="img" aria-label="Grafik pendapatan harian ${esc(label)}">${data.values.map((value,index)=>`<div class="bar-column" title="${index+1} ${esc(label)}: ${money(value)}"><div class="bar-value">${value?money(value).replace(/,00$/,''):''}</div><div class="bar-track"><span style="height:${data.max?Math.max(2,value/data.max*100):0}%"></span></div><small>${index+1}</small></div>`).join('')}</div>`;anchor.insertAdjacentElement('afterend',section)}
function mountReportWaiterColumn(){const table=$('.report-table.detailed'),head=table?.tHead?.rows[0],rows=filteredTransactions().slice().reverse();if(!head||!rows.length)return;const th=document.createElement('th');th.textContent='Waiter';head.insertBefore(th,head.cells[3]);[...table.tBodies[0].rows].forEach((row,index)=>{const td=document.createElement('td');td.textContent=rows[index]?.waiter||'—';row.insertBefore(td,row.cells[3])})}
function roleLabel(role){return role==='owner'?'Owner':role==='admin'?'Admin':'Kasir'}
function totals(cart=currentCart()){const subtotal=cart.reduce((s,x)=>s+x.price*x.qty,0),taxableSubtotal=cart.reduce((s,x)=>s+(x.taxable===false?0:x.price*x.qty),0),tax=Math.round(taxableSubtotal*.1);return{subtotal,taxableSubtotal,tax,total:subtotal+tax}}
function paymentMatches(x,code){return x.paymentCode===code||(code==='cash'&&x.payment==='Tunai')||(code==='card'&&x.payment==='Kartu')||(code==='qris'&&x.payment==='QRIS')}
function filteredTransactions(){return state.transactions.filter(x=>{const date=x.date||x.timestamp?.slice(0,10)||businessDate();return(!reportFrom||date>=reportFrom)&&(!reportTo||date<=reportTo)&&(reportPayment==='all'||paymentMatches(x,reportPayment))&&(reportCashier==='all'||String(x.cashierId)===reportCashier)})}
function renderReports(){const rows=filteredTransactions(),sales=rows.reduce((s,x)=>s+(x.total||0),0),subtotal=rows.reduce((s,x)=>s+(x.subtotal||0),0),taxable=rows.reduce((s,x)=>s+(x.taxableSubtotal??x.subtotal??0),0),tax=rows.reduce((s,x)=>s+(x.tax||0),0),count=rows.length,payments=['cash','card','qris'].map(code=>({code,total:rows.filter(x=>paymentMatches(x,code)).reduce((s,x)=>s+x.total,0)})),items={};rows.forEach(x=>(x.lineItems||[]).forEach(i=>{const key=i.name;items[key]??={name:i.name,qty:0,total:0};items[key].qty+=i.qty;items[key].total+=i.lineTotal}));const top=Object.values(items).sort((a,b)=>b.qty-a.qty).slice(0,5);return `<div class="report-filters"><label>Dari<input id="reportFrom" type="date" value="${reportFrom}"></label><label>Sampai<input id="reportTo" type="date" value="${reportTo}"></label><label>Pembayaran<select id="reportPayment"><option value="all">Semua</option><option value="cash" ${reportPayment==='cash'?'selected':''}>Tunai</option><option value="card" ${reportPayment==='card'?'selected':''}>Kartu</option><option value="qris" ${reportPayment==='qris'?'selected':''}>QRIS</option></select></label><label>Kasir<select id="reportCashier"><option value="all">Semua</option>${state.users.map(u=>`<option value="${u.id}" ${reportCashier===String(u.id)?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><button class="secondary" id="exportReport">Ekspor CSV</button></div><div class="report-cards"><div class="stat"><small>Penjualan kotor</small><strong>${money(subtotal)}</strong></div><div class="stat"><small>Dasar kena pajak</small><strong>${money(taxable)}</strong></div><div class="stat"><small>Pajak terkumpul</small><strong>${money(tax)}</strong></div><div class="stat"><small>Penjualan bersih</small><strong>${money(sales)}</strong></div><div class="stat"><small>${t('transactions')}</small><strong>${count}</strong></div><div class="stat"><small>${t('average')}</small><strong>${money(count?sales/count:0)}</strong></div></div><div class="report-breakdown"><div class="panel"><h3>Metode pembayaran</h3>${payments.map(p=>`<div class="total-row"><span>${t(p.code)}</span><strong>${money(p.total)}</strong></div>`).join('')}</div><div class="panel"><h3>Menu terlaris</h3>${top.map((x,i)=>`<div class="total-row"><span>${i+1}. ${esc(x.name)} · ${x.qty} porsi</span><strong>${money(x.total)}</strong></div>`).join('')||'<p class="muted">Belum ada data item.</p>'}</div></div><h3>Rincian transaksi</h3><div class="report-table-wrap"><table class="report-table detailed"><thead><tr><th>Tanggal / waktu</th><th>Invoice / order</th><th>Meja / orang</th><th>Kasir</th><th>Pembayaran</th><th>Subtotal</th><th>Pajak</th><th>Total</th><th>Item</th></tr></thead><tbody>${rows.slice().reverse().map(x=>`<tr><td>${esc(x.date||'—')}<br><small>${esc(x.time||'—')}</small></td><td><strong>${esc(x.id)}</strong><br><small>${esc(x.orderId||'Data lama')}</small></td><td>${esc(x.table||'—')}${x.splitPerson?`<br><small>Orang ${x.splitPerson}</small>`:''}</td><td>${esc(x.cashier||'—')}</td><td>${esc(x.payment||'—')}</td><td>${money(x.subtotal||0)}</td><td>${money(x.tax||0)}</td><td><strong>${money(x.total||0)}</strong></td><td><details><summary>${(x.lineItems||x.items||[]).length} item</summary><div class="detail-items">${x.lineItems?.map(i=>`${i.qty}× ${esc(i.name)} — ${money(i.lineTotal)}${i.taxable?'':' (tanpa pajak)'}`).join('<br>')||(x.items||[]).map(esc).join('<br>')||'—'}</div></details></td></tr>`).join('')||'<tr><td colspan="9">Tidak ada transaksi untuk filter ini.</td></tr>'}</tbody></table></div>`}
function exportReportCSV(){const rows=filteredTransactions(),safe=v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return `"${s.replaceAll('"','""')}"`},header=['Tanggal','Waktu','Invoice','Order','Meja','Split orang','Waiter','Kasir','Pembayaran','Subtotal','Dasar kena pajak','Pajak','Total','Item'],lines=rows.map(x=>[x.date,x.time,x.id,x.orderId,x.table,x.splitPerson||'',x.waiter||'',x.cashier,x.payment,x.subtotal,x.taxableSubtotal,x.tax,x.total,(x.lineItems||[]).map(i=>`${i.qty}x ${i.name}`).join('; ')].map(safe).join(',')),blob=new Blob(['\ufeff'+[header.map(safe).join(','),...lines].join('\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`laporan-anda-pos-${businessDate()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function transactionDate(transaction){return transaction.date||transaction.timestamp?.slice(0,10)||''}
function todayTransactions(){const today=businessDate();return state.transactions.filter(transaction=>transactionDate(transaction)===today)}
function transactionsForShift(shift=state.shift){return shift?.id?state.transactions.filter(transaction=>transaction.shiftId===shift.id):[]}
function summarizeTransactions(transactions){const byPayment={cash:0,card:0,qris:0};for(const transaction of transactions){const code=['cash','card','qris'].find(method=>paymentMatches(transaction,method));if(code)byPayment[code]+=Number(transaction.total)||0}return{count:transactions.length,sales:transactions.reduce((sum,transaction)=>sum+(Number(transaction.subtotal)||0)-(Number(transaction.discountAmount)||0),0),collected:transactions.reduce((sum,transaction)=>sum+(Number(transaction.total)||0),0),tax:transactions.reduce((sum,transaction)=>sum+(Number(transaction.tax)||0),0),byPayment}}
function clockTime(value){const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}
function dateTime(value){const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString('id-ID',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function suggestedShiftName(){const hour=new Date().getHours(),period=hour<11?'Pagi':hour<17?'Siang':'Malam';return `Shift ${period}`}
function renderShift(){const today=summarizeTransactions(todayTransactions()),active=summarizeTransactions(transactionsForShift()),history=state.shiftHistory||[];return `<div class="section-title"><div><h2>Shift kasir</h2><p class="muted">Penjualan hari ini dihitung hanya dari transaksi tanggal ${businessDate()}.</p></div><button class="${state.shift.open?'danger':'primary'}" id="toggleShift">${state.shift.open?t('endShift'):t('startShift')}</button></div><div class="cards"><div class="stat"><small>Penjualan hari ini</small><strong>${money(today.sales)}</strong></div><div class="stat"><small>Transaksi hari ini</small><strong>${today.count}</strong></div><div class="stat"><small>Status shift</small><strong>${state.shift.open?'Aktif':'Tutup'}</strong></div></div><br>${state.shift.open?`<div class="panel"><div class="section-title"><div><h3>${esc(state.shift.name)}</h3><p>${esc(state.shift.cashierName)} · Dibuka ${dateTime(state.shift.openedAt)}</p></div><span class="status-pill">Shift aktif</span></div><div class="cards"><div class="stat"><small>Penjualan shift</small><strong>${money(active.sales)}</strong></div><div class="stat"><small>Transaksi shift</small><strong>${active.count}</strong></div><div class="stat"><small>Saldo awal</small><strong>${money(state.shift.openingCash||0)}</strong></div></div><br><div class="report-breakdown"><div class="total-row"><span>Tunai</span><strong>${money(active.byPayment.cash)}</strong></div><div class="total-row"><span>Kartu</span><strong>${money(active.byPayment.card)}</strong></div><div class="total-row"><span>QRIS</span><strong>${money(active.byPayment.qris)}</strong></div><div class="total-row grand"><span>Uang tunai yang seharusnya</span><strong>${money((state.shift.openingCash||0)+active.byPayment.cash)}</strong></div></div></div><br>`:'<div class="panel"><h3>Tidak ada shift aktif</h3><p class="muted">Mulai shift untuk mengelompokkan transaksi kasir dan mencatat saldo tunai.</p></div><br>'}<h3>Riwayat shift</h3><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Shift</th><th>Kasir</th><th>Dibuka / ditutup</th><th>Transaksi</th><th>Penjualan</th><th>Selisih kas</th></tr></thead><tbody>${history.slice(0,30).map(shift=>`<tr><td><strong>${esc(shift.name)}</strong><br><small>${esc(shift.id)}</small></td><td>${esc(shift.cashierName||'—')}</td><td>${dateTime(shift.openedAt)}<br><small>${dateTime(shift.closedAt)}</small></td><td>${shift.transactionCount||0}</td><td>${money(shift.sales||0)}</td><td>${money(shift.difference||0)}</td></tr>`).join('')||'<tr><td colspan="6">Belum ada shift yang ditutup.</td></tr>'}</tbody></table></div>`}
function showStartShift(){if(state.shift.open){toast('Masih ada shift aktif.');return}openModal(`<h2>Mulai shift kasir</h2><form id="startShiftForm"><label class="field"><span>Nama shift</span><input name="name" value="${esc(suggestedShiftName())}" required maxlength="40" autofocus></label><label class="field"><span>Saldo awal laci kas (Rp)</span><input name="openingCash" type="number" min="0" step="1" inputmode="numeric" value="0" required></label><div class="modal-actions"><button type="button" class="secondary close-modal">Batal</button><button class="primary">Mulai shift</button></div></form>`);$('#startShiftForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target),now=new Date();state.shift={id:nextDocumentId('SFT','nextShiftNumber'),open:true,name:String(form.get('name')).trim(),cashierId:state.user.id,cashierName:state.user.name,openedAt:now.toISOString(),openingCash:Math.max(0,Number(form.get('openingCash'))||0)};await save();closeModal();render();toast(`${state.shift.name} dimulai.`)}}
function showEndShift(){if(!state.shift.open){toast('Tidak ada shift aktif.');return}const summary=summarizeTransactions(transactionsForShift()),expectedCash=(state.shift.openingCash||0)+summary.byPayment.cash;openModal(`<h2>Akhiri ${esc(state.shift.name)}</h2><div class="cards"><div class="stat"><small>Penjualan shift</small><strong>${money(summary.sales)}</strong></div><div class="stat"><small>Transaksi</small><strong>${summary.count}</strong></div><div class="stat"><small>Kas seharusnya</small><strong>${money(expectedCash)}</strong></div></div><form id="endShiftForm"><label class="field"><span>Uang tunai aktual di laci (Rp)</span><input name="closingCash" type="number" min="0" step="1" inputmode="numeric" value="${expectedCash}" required autofocus></label><p>Selisih kas: <strong id="cashDifference">${money(0)}</strong></p><div class="modal-actions"><button type="button" class="secondary close-modal">Batal</button><button class="danger">Konfirmasi akhiri shift</button></div></form>`);const input=$('#endShiftForm [name="closingCash"]'),difference=$('#cashDifference');input.oninput=()=>difference.textContent=money((Number(input.value)||0)-expectedCash);$('#endShiftForm').onsubmit=async event=>{event.preventDefault();const closedAt=new Date().toISOString(),closingCash=Math.max(0,Number(new FormData(event.target).get('closingCash'))||0),closed={...state.shift,open:false,closedAt,closingCash,expectedCash,difference:closingCash-expectedCash,transactionCount:summary.count,sales:summary.sales,payments:summary.byPayment};state.shiftHistory=[closed,...(state.shiftHistory||[])];state.shift={open:false,lastClosedAt:closedAt,lastShiftId:closed.id};await save();closeModal();render();toast(`${closed.name} diakhiri. Selisih kas ${money(closed.difference)}.`)}}
function renderOrder(){const o=$('#orderPanel'),cart=currentCart(),bills=currentSplitBills(),sum=totals(cart),orderId=state.orderIds[cartKey()];o.innerHTML=`<div class="order-head"><div><p class="eyebrow">${state.orderType==='dineIn'?'Meja '+state.table:'Takeaway'}</p><h2>${orderId||'Pesanan baru'}</h2></div><button class="icon-btn" id="clearCart">×</button></div><div class="order-type"><button data-type="dineIn" class="${state.orderType==='dineIn'?'active':''}">${t('dineIn')}</button><button data-type="takeaway" class="${state.orderType==='takeaway'?'active':''}">${t('takeaway')}</button></div>${bills.length?`<div class="saved-bills"><div class="saved-bills-title"><strong>Bill tersimpan</strong><button class="mini" id="manageBills">Kelola semua</button></div>${bills.map(b=>{const bt=totals(b.items),quantity=b.items.reduce((s,i)=>s+i.qty,0);return `<div class="saved-bill-card"><div class="saved-bill-summary"><strong>${esc(b.label)}</strong><small>${quantity} ${state.language==='en'?'portions':'porsi'} · ${money(bt.total)}</small></div><div class="saved-bill-card-actions"><button class="mini pay-saved-bill" data-pay-bill="${b.id}">Bayar</button></div><div class="saved-bill-items">${b.items.map(i=>`<span><b>${Number(i.qty)||0}×</b><em>${esc(state.language==='en'?(i.en||i.name):i.name)}</em></span>`).join('')}</div></div>`}).join('')}</div>`:''}<div class="cart">${cart.length?cart.map(x=>`<div class="cart-item"><div><strong>${esc(state.language==='id'?x.name:x.en)}</strong><small>${money(x.price)} · ${x.taxable===false?'tanpa pajak':'tax 10%'}</small></div><div class="qty"><button data-minus="${x.id}">−</button><b>${x.qty}</b><button data-plus="${x.id}">+</button></div></div>`).join(''):`<div class="cart-empty">◌<br><br>${bills.length?'Semua item saat ini berada dalam bill tersimpan.':t('empty')}</div>`}</div><div class="totals"><div class="total-row"><span>Sisa pesanan utama</span><b>${money(sum.subtotal)}</b></div><div class="total-row"><span>Dasar kena pajak</span><b>${money(sum.taxableSubtotal)}</b></div><div class="total-row"><span>${t('tax')}</span><b>${money(sum.tax)}</b></div><div class="total-row grand"><span>${t('total')}</span><b>${money(sum.total)}</b></div></div><div class="pay-actions"><button class="secondary" id="splitBtn" ${!cart.length&&!bills.length?'disabled':''}>${bills.length?'Kelola split':'Split bill'}</button><button class="primary" id="payBtn" ${!cart.length?'disabled':''}>${t('pay')} · ${money(sum.total)}</button></div>`;decorateOrderPanel();bindOrder();}
function bindView(){document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>add(+b.dataset.product));document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>selectPOSCategory(b.dataset.cat));const s=$('#search');if(s)s.oninput=e=>{search=e.target.value;renderView();const next=$('#search');next?.focus();next?.setSelectionRange(next.value.length,next.value.length)};const ms=$('#menuMgmtSearch');if(ms)ms.oninput=e=>{menuMgmtSearchQuery=e.target.value;renderView();const next=$('#menuMgmtSearch');next?.focus();next?.setSelectionRange(next.value.length,next.value.length)};document.querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{state.table=b.dataset.table;state.orderType='dineIn';state.activeView='pos';render();save()});document.querySelectorAll('.finish-ticket').forEach(b=>b.onclick=()=>{const x=state.tickets.find(t=>t.id===b.dataset.ticket);if(x.status==='ready')state.tickets=state.tickets.filter(t=>t.id!==x.id);else x.status='ready';render();save()});const ts=$('#toggleShift');if(ts)ts.onclick=()=>state.shift.open?showEndShift():showStartShift();const addCategory=$('#addCategory'),addProduct=$('#addProduct'),addUser=$('#addUser');if(addCategory)addCategory.onclick=()=>showCategoryForm();if(addProduct)addProduct.onclick=()=>showProductForm();if(addUser)addUser.onclick=()=>showUserForm();document.querySelectorAll('.edit-category').forEach(b=>b.onclick=()=>showCategoryForm(b.dataset.category));document.querySelectorAll('.delete-category').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.category));document.querySelectorAll('.edit-product').forEach(b=>b.onclick=()=>showProductForm(+b.dataset.id));document.querySelectorAll('.delete-product').forEach(b=>b.onclick=()=>deleteProduct(+b.dataset.id));document.querySelectorAll('.edit-user').forEach(b=>b.onclick=()=>showUserForm(+b.dataset.id));document.querySelectorAll('.toggle-user').forEach(b=>b.onclick=()=>toggleUser(+b.dataset.id));const rf=$('#reportFrom'),rt=$('#reportTo'),rp=$('#reportPayment'),rc=$('#reportCashier'),re=$('#exportReport');if(rf)rf.onchange=()=>{reportFrom=rf.value;renderView()};if(rt)rt.onchange=()=>{reportTo=rt.value;renderView()};if(rp)rp.onchange=()=>{reportPayment=rp.value;renderView()};if(rc)rc.onchange=()=>{reportCashier=rc.value;renderView()};if(re)re.onclick=exportReportCSV}


function showClearCartConfirmation(){if(!currentCart().length)return;openModal(`<h2>${state.language==='en'?'Clear all cart items?':'Hapus semua item cart?'}</h2><p>${state.language==='en'?'All unsaved items in the current order will be removed. Saved split bills will not be changed.':'Semua item yang belum disimpan pada pesanan ini akan dihapus. Saved split bill tidak akan berubah.'}</p><div class="modal-actions"><button class="secondary close-modal">${state.language==='en'?'Cancel':'Batal'}</button><button class="danger" id="confirmClearCart">${state.language==='en'?'Clear all items':'Hapus semua item'}</button></div>`);$('#confirmClearCart').onclick=async()=>{const key=cartKey();replaceCurrentCart([]);if(!currentSplitBills().length){delete state.orderIds[key];delete state.orderMeta[key]}await save();closeModal();renderOrder();toast(state.language==='en'?'Cart cleared.':'Semua item cart dihapus.')}}

function bindOrder(){document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.orderType=b.dataset.type;renderOrder();save()});document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>change(+b.dataset.plus,1));document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>change(+b.dataset.minus,-1));$('#clearCart').onclick=showClearCartConfirmation;$('#payBtn').onclick=showPayment;$('#splitBtn').onclick=showSplit;const manage=$('#manageBills');if(manage)manage.onclick=showSplit;document.querySelectorAll('[data-pay-bill]').forEach(b=>b.onclick=()=>showSavedBillPayment(b.dataset.payBill))}
function add(id){if(!state.orderMeta[cartKey()]&&!allOpenItems().length){showWaiterPrompt(id);return}addProductToCart(id)}
function showWaiterPrompt(productId){openModal(`<h2>Order baru</h2><p>Masukkan nama waiter yang menangani tamu ini.</p><form id="waiterForm"><label class="field"><span>Nama waiter</span><input name="waiter" required maxlength="50" autofocus autocomplete="off" placeholder="Contoh: Komang"></label><div class="modal-actions"><button type="button" class="secondary close-modal">${t('close')}</button><button class="primary">Mulai order</button></div></form>`);$('#waiterForm').onsubmit=async e=>{e.preventDefault();const waiter=String(new FormData(e.target).get('waiter')).trim();if(!waiter)return;state.orderMeta[cartKey()]={waiter,createdAt:new Date().toISOString()};closeModal();addProductToCart(productId)}}
function addProductToCart(id){const cart=currentCart(),p=state.products.find(x=>x.id===id),item=cart.find(x=>x.id===id);if(!p.unlimitedStock&&reservedQuantity(id)>=p.stock){toast(`Stok ${p.name} tidak mencukupi.`);return}ensureOrderId();if(item)item.qty++;else cart.push({...p,qty:1});renderOrder();decorateOrderPanel();save()}
function change(id,n){const key=cartKey(),cart=currentCart(),x=cart.find(x=>x.id===id);x.qty+=n;if(x.qty<=0)replaceCurrentCart(cart.filter(y=>y.id!==id));if(!currentCart().length&&!currentSplitBills().length){delete state.orderIds[key];delete state.orderMeta[key]}renderOrder();save()}
function showPayment(){const sum=totals();openModal(`<h2>${t('confirmPay')}</h2><p>${state.orderIds[cartKey()]} · ${state.orderType==='dineIn'?'Meja '+state.table:'Takeaway'} · <strong>${money(sum.total)}</strong></p><div class="payment-grid">${[['cash','💵'],['card','💳'],['qris','▦']].map(([k,i])=>`<button data-payment="${k}">${i}<span>${t(k)}</span></button>`).join('')}</div><div class="modal-actions"><button class="secondary close-modal">${t('close')}</button></div>`);document.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>completePayment(b.dataset.payment))}
function showSplit(){const cart=currentCart(),bills=currentSplitBills();openModal(`<h2>Split bill fleksibel</h2><p>Simpan bill satu orang sekarang. Sisa pesanan tetap berada di meja dan dapat dibagi lagi kapan saja.</p><div class="split-manager-summary"><div><small>Pesanan utama</small><strong>${cart.reduce((s,i)=>s+i.qty,0)} porsi · ${money(totals(cart).total)}</strong></div><div><small>Bill tersimpan</small><strong>${bills.length}</strong></div></div><div class="saved-bill-list">${bills.map(b=>{const sum=totals(b.items);return `<article><div><span class="status-pill">Tertunda</span><h3>${esc(b.label)}</h3><p>${b.items.map(i=>`${i.qty}× ${esc(i.name)}`).join('<br>')}</p><strong>${money(sum.total)}</strong></div><div class="saved-bill-actions"><button class="mini manage-saved" data-manage-bill="${b.id}">Tambah / ubah</button><button class="mini pay-saved" data-pay-bill-modal="${b.id}">Bayar</button><button class="mini danger-text return-saved" data-return-bill="${b.id}">Kembalikan</button></div></article>`}).join('')||'<p class="muted">Belum ada bill tersimpan untuk meja ini.</p>'}</div><div class="modal-actions"><button class="secondary close-modal">${t('close')}</button>${cart.length?'<button class="primary" id="createSavedBill">+ Simpan bill orang berikutnya</button>':''}</div>`);$('#modalBody').classList.add('wide');const create=$('#createSavedBill');if(create)create.onclick=()=>showBillAllocation();document.querySelectorAll('[data-manage-bill]').forEach(b=>b.onclick=()=>showBillAllocation(b.dataset.manageBill));document.querySelectorAll('[data-pay-bill-modal]').forEach(b=>b.onclick=()=>showSavedBillPayment(b.dataset.payBillModal));document.querySelectorAll('[data-return-bill]').forEach(b=>b.onclick=()=>returnWholeBill(b.dataset.returnBill))}
function showSplitAllocation(people){const cart=currentCart(),alloc=cart.map(()=>Array(people).fill(0));openModal(`<h2>Alokasi bill · ${people} orang</h2><p class="muted">Gunakan tombol + untuk memberikan porsi. Jika sisa 0, menu tidak dapat ditambahkan ke orang lain sebelum dikurangi.</p><form id="splitAllocation"><div class="split-scroll"><table class="split-table"><thead><tr><th>Menu</th><th>Pesanan</th><th>Sisa</th>${Array.from({length:people},(_,i)=>`<th>Orang ${i+1}</th>`).join('')}</tr></thead><tbody>${cart.map((item,row)=>`<tr><td><strong>${esc(item.name)}</strong><small>${item.taxable===false?'Tanpa pajak':'Tax 10%'}</small></td><td>${item.qty}</td><td><strong class="split-remaining" data-remaining="${row}">${item.qty}</strong></td>${alloc[row].map((_qty,person)=>`<td><div class="split-stepper"><button type="button" data-split-minus="${row}:${person}">−</button><b data-allocation="${row}:${person}">0</b><button type="button" data-split-plus="${row}:${person}">+</button></div></td>`).join('')}</tr>`).join('')}</tbody></table></div><h3>Metode pembayaran</h3><div class="split-methods">${Array.from({length:people},(_,i)=>`<label class="field"><span>Orang ${i+1}</span><select data-split-method="${i}"><option value="cash">Tunai</option><option value="card">Kartu</option><option value="qris">QRIS</option></select><strong data-person-total="${i}"></strong></label>`).join('')}</div><p class="form-error" id="splitError"></p><div class="modal-actions"><button type="button" class="secondary" id="splitBack">Kembali</button><button class="primary">Bayar semua bill</button></div></form>`);$('#modalBody').classList.add('wide');const value=(row,person)=>alloc[row][person],buildBills=()=>Array.from({length:people},(_,person)=>cart.flatMap((item,row)=>value(row,person)?[{...item,qty:value(row,person)}]:[])),refresh=()=>{cart.forEach((item,row)=>{const assigned=alloc[row].reduce((a,b)=>a+b,0),remaining=item.qty-assigned;$(`[data-remaining="${row}"]`).textContent=remaining;document.querySelectorAll(`[data-split-plus^="${row}:"]`).forEach(b=>b.disabled=remaining===0);for(let person=0;person<people;person++){const display=$(`[data-allocation="${row}:${person}"]`);display.textContent=value(row,person);$(`[data-split-minus="${row}:${person}"]`).disabled=value(row,person)===0}});buildBills().forEach((bill,i)=>$(`[data-person-total="${i}"]`).textContent=money(totals(bill).total));$('#splitError').textContent=''};document.querySelectorAll('[data-split-plus]').forEach(b=>b.onclick=()=>{const[row,person]=b.dataset.splitPlus.split(':').map(Number),assigned=alloc[row].reduce((a,c)=>a+c,0);if(assigned<cart[row].qty)alloc[row][person]++;refresh()});document.querySelectorAll('[data-split-minus]').forEach(b=>b.onclick=()=>{const[row,person]=b.dataset.splitMinus.split(':').map(Number);if(alloc[row][person]>0)alloc[row][person]--;refresh()});refresh();$('#splitBack').onclick=showSplit;$('#splitAllocation').onsubmit=e=>{e.preventDefault();for(let row=0;row<cart.length;row++){const assigned=alloc[row].reduce((a,b)=>a+b,0);if(assigned!==cart[row].qty){$('#splitError').textContent=`${cart[row].name} masih memiliki ${cart[row].qty-assigned} porsi yang belum dibagikan.`;return}}const bills=buildBills();if(bills.some(b=>!b.length)){$('#splitError').textContent='Setiap orang harus memiliki minimal satu porsi.';return}const methods=Array.from({length:people},(_,i)=>$(`[data-split-method="${i}"]`).value);completeSplitPayment(bills,methods)}}
function showBillAllocation(billId=null){const cart=currentCart(),bill=currentSplitBills().find(b=>b.id===billId),selected=cart.map(()=>0);if(!cart.length&&!bill){showSplit();toast('Tidak ada sisa pesanan untuk disimpan.');return}openModal(`<h2>${bill?`Tambah item ke ${esc(bill.label)}`:'Bill orang baru'}</h2><p class="muted">Pilih sebagian item saja. Item lain tetap tersimpan di pesanan utama meja.</p>${bill?`<div class="current-bill-items"><strong>Isi ${esc(bill.label)} saat ini</strong>${bill.items.map(i=>`<div><span>${i.qty}× ${esc(i.name)}</span><button class="mini return-one" data-return-item="${i.id}">Kembalikan 1</button></div>`).join('')}</div>`:''}<form id="saveBillForm"><div class="split-scroll"><table class="split-table"><thead><tr><th>Menu tersisa</th><th>Tersedia</th><th>Pindahkan ke bill</th></tr></thead><tbody>${cart.map((item,row)=>`<tr><td><strong>${esc(item.name)}</strong><small>${item.taxable===false?'Tanpa pajak':'Tax 10%'}</small></td><td data-source-left="${row}">${item.qty}</td><td><div class="split-stepper"><button type="button" data-save-minus="${row}">−</button><b data-save-qty="${row}">0</b><button type="button" data-save-plus="${row}">+</button></div></td></tr>`).join('')||'<tr><td colspan="3">Tidak ada sisa item. Gunakan tombol Kembalikan 1 untuk mengubah bill.</td></tr>'}</tbody></table></div><div class="split-manager-summary"><div><small>Total bill setelah disimpan</small><strong id="savedBillTotal">${money(totals(bill?.items||[]).total)}</strong></div></div><p class="form-error" id="saveBillError"></p><div class="modal-actions"><button type="button" class="secondary" id="backSplitManager">Kembali</button>${cart.length?'<button class="primary">Simpan bill</button>':''}</div></form>`);$('#modalBody').classList.add('wide');const refresh=()=>{cart.forEach((item,row)=>{$(`[data-save-qty="${row}"]`).textContent=selected[row];$(`[data-source-left="${row}"]`).textContent=item.qty-selected[row];$(`[data-save-minus="${row}"]`).disabled=selected[row]===0;$(`[data-save-plus="${row}"]`).disabled=selected[row]===item.qty});const preview=[...(bill?.items||[]),...cart.flatMap((item,row)=>selected[row]?[{...item,qty:selected[row]}]:[])];$('#savedBillTotal').textContent=money(totals(preview).total)};document.querySelectorAll('[data-save-plus]').forEach(b=>b.onclick=()=>{const row=Number(b.dataset.savePlus);if(selected[row]<cart[row].qty)selected[row]++;refresh()});document.querySelectorAll('[data-save-minus]').forEach(b=>b.onclick=()=>{const row=Number(b.dataset.saveMinus);if(selected[row]>0)selected[row]--;refresh()});document.querySelectorAll('[data-return-item]').forEach(b=>b.onclick=()=>returnBillItem(billId,+b.dataset.returnItem));refresh();$('#backSplitManager').onclick=showSplit;$('#saveBillForm').onsubmit=async e=>{e.preventDefault();if(!selected.some(Boolean)){$('#saveBillError').textContent='Pilih minimal satu porsi untuk disimpan.';return}let target=bill;if(!target){const key=cartKey(),person=state.splitPersonCounters[key]||1;state.splitPersonCounters[key]=person+1;target={id:`SB-${String(state.nextSplitBillNumber++).padStart(4,'0')}`,personNumber:person,label:`Orang ${person}`,items:[],createdAt:new Date().toISOString()};currentSplitBills().push(target)}cart.forEach((item,row)=>{if(selected[row])mergeItem(target.items,item,selected[row])});replaceCurrentCart(cart.flatMap((item,row)=>item.qty-selected[row]>0?[{...item,qty:item.qty-selected[row]}]:[]));await save();render();showSplit();toast(`${target.label} berhasil disimpan.`)}}
async function returnBillItem(billId,productId){const bills=currentSplitBills(),bill=bills.find(b=>b.id===billId),item=bill.items.find(i=>i.id===productId);mergeItem(currentCart(),item,1);item.qty--;if(item.qty===0)bill.items=bill.items.filter(i=>i.id!==productId);if(!bill.items.length)state.splitBills[cartKey()]=bills.filter(b=>b.id!==billId);await save();render();bill.items.length?showBillAllocation(billId):showSplit()}
async function returnWholeBill(billId){const bills=currentSplitBills(),bill=bills.find(b=>b.id===billId);bill.items.forEach(item=>mergeItem(currentCart(),item));state.splitBills[cartKey()]=bills.filter(b=>b.id!==billId);await save();render();showSplit();toast(`${bill.label} dikembalikan ke pesanan utama.`)}
function showSavedBillPayment(billId){const bill=currentSplitBills().find(b=>b.id===billId),sum=totals(bill.items);openModal(`<h2>Bayar ${esc(bill.label)}</h2><p>${state.orderIds[cartKey()]} · ${state.orderType==='dineIn'?'Meja '+state.table:'Takeaway'} · <strong>${money(sum.total)}</strong></p><div class="pending-bill-preview">${bill.items.map(i=>`<div class="total-row"><span>${i.qty}× ${esc(i.name)}</span><strong>${money(i.price*i.qty)}</strong></div>`).join('')}</div><div class="payment-grid">${[['cash','💵'],['card','💳'],['qris','▦']].map(([k,i])=>`<button data-saved-payment="${k}">${i}<span>${t(k)}</span></button>`).join('')}</div><div class="modal-actions"><button class="secondary" id="backSavedBills">Kembali</button></div>`);$('#backSavedBills').onclick=showSplit;document.querySelectorAll('[data-saved-payment]').forEach(b=>b.onclick=()=>completeSavedBillPayment(billId,b.dataset.savedPayment))}
function openModal(html){$('#modalBody').classList.remove('wide');$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden');document.querySelectorAll('.close-modal').forEach(b=>b.onclick=closeModal)}function closeModal(){if(sessionLocked)return;$('#modal').classList.add('hidden')}
function makeTransaction(cart,method,person=null){const sum=totals(cart),now=new Date(),orderId=state.orderIds[cartKey()]||ensureOrderId(),meta=state.orderMeta[cartKey()]||{};return{id:nextDocumentId('INV','nextInvoiceNumber'),orderId,date:businessDate(now),timestamp:now.toISOString(),time:now.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),payment:t(method),paymentCode:method,cashier:state.user.name,cashierId:state.user.id,shiftId:state.shift.open?state.shift.id:null,waiter:meta.waiter||'—',table:state.orderType==='dineIn'?state.table:'Takeaway',splitPerson:person,...sum,lineItems:cart.map(x=>({productId:x.id,name:x.name,nameEn:x.en,category:x.category,qty:x.qty,price:x.price,taxable:x.taxable!==false,lineTotal:x.price*x.qty})),items:cart.map(x=>`${x.qty}× ${x.name}`)}}
function receiptHTML(trx,index=0){const logo=state.settings.brandLogo?`<img class="receipt-logo" src="${state.settings.brandLogo}" alt="Logo">`:'';return `<div class="receipt" data-receipt="${index}">${logo}<h2>${esc(state.settings.restaurantName)}</h2><p style="text-align:center">${trx.id}<br>${trx.orderId} · ${trx.time}<br>${trx.table}${trx.splitPerson?` · Orang ${trx.splitPerson}`:''}<br>Waiter: ${esc(trx.waiter||'—')}</p>${trx.lineItems.map(x=>`<div class="receipt-line"><span>${x.qty}× ${esc(state.language==='en'?(x.nameEn||x.en||state.products.find(p=>p.id===x.productId)?.en||x.name):x.name)}</span><span>${money(x.lineTotal)}</span></div>`).join('')}<div class="receipt-line receipt-total"><span>${t('subtotal')}</span><span>${money(trx.subtotal)}</span></div><div class="receipt-line"><span>Dasar kena pajak</span><span>${money(trx.taxableSubtotal)}</span></div><div class="receipt-line"><span>${t('tax')}</span><span>${money(trx.tax)}</span></div><div class="receipt-line"><strong>${t('total')}</strong><strong>${money(trx.total)}</strong></div><p style="text-align:center">${trx.payment}<br>Kasir: ${esc(trx.cashier)}<br><br>Terima kasih · Thank you</p></div>`}
function nativeReceiptFromElement(receipt){const children=[...receipt.children],paragraphs=children.filter(x=>x.tagName==='P'),textLines=element=>String(element?.innerText||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);return{logo:state.settings.brandLogo||'',heading:receipt.querySelector('h2')?.textContent?.trim()||state.settings.restaurantName,meta:textLines(paragraphs[0]),rows:children.filter(x=>x.classList.contains('receipt-line')).map(row=>{const cells=[...row.children];return{left:cells[0]?.textContent?.trim()||'',right:cells[1]?.textContent?.trim()||'',sectionStart:row.classList.contains('receipt-total'),emphasis:row.classList.contains('receipt-total')||Boolean(row.querySelector('strong'))}}),notes:paragraphs.slice(1,-1).flatMap(textLines),footer:textLines(paragraphs.at(-1))}}
async function printReceipt(index=null){const receipts=[...document.querySelectorAll('[data-receipt]')].filter(r=>index===null||Number(r.dataset.receipt)===index);if(!receipts.length){toast('Struk tidak ditemukan.');return}if(!window.desktop){window.print();return}for(const receipt of receipts){const result=await window.desktop.print({html:receipt.outerHTML,nativeReceipt:nativeReceiptFromElement(receipt),silent:state.settings.silentPrint,deviceName:state.settings.printerName,directMode:state.settings.directPrintMode||'escpos',nativeColumns:Number(state.settings.directPrintColumns)||42,autoCut:state.settings.autoCut!==false,cutFeedLines:Number(state.settings.cutFeedLines)||8,contentWidth:Number(state.settings.receiptContentWidth)||64,fontStyle:state.settings.receiptFontStyle||'clear'});if(!result?.success){if(result?.failureReason!=='cancelled')toast(`Cetak gagal: ${result?.failureReason||'periksa printer dan ukuran kertas 80 mm.'}`);return}}toast(`${receipts.length} struk berhasil dikirim ke printer.`)}
async function finalizeOrder(transactions,originalCart){const key=cartKey(),orderId=state.orderIds[key],items=originalCart.map(x=>`${x.qty}× ${x.name}`),time=transactions[0].time;state.transactions.push(...transactions);if(state.settings.kitchenEnabled)state.tickets.unshift({id:`D-${orderId.split('-').pop()}`,orderId,table:state.orderType==='dineIn'?state.table:'TA',items,status:'cooking',time});originalCart.forEach(x=>{const p=state.products.find(y=>y.id===x.id);if(p&&!p.unlimitedStock)p.stock=Math.max(0,p.stock-x.qty)});replaceCurrentCart([]);delete state.orderIds[key];delete state.orderMeta[key];delete state.splitPersonCounters[key];await save();render();const printButtons=transactions.length>1?transactions.map((trx,i)=>`<button class="secondary print-person" data-print-person="${i}">Cetak bill Orang ${trx.splitPerson}</button>`).join(''):`<button class="primary" id="printReceipt">${t('print')}</button>`;openModal(`${transactions.map(receiptHTML).join('<hr class="receipt-separator">')}<div class="modal-actions receipt-actions split-print-actions"><button class="secondary close-modal">${t('close')}</button>${printButtons}${transactions.length>1?'<button class="primary" id="printAllReceipts">Cetak semua bill</button>':''}</div>`);if(transactions.length>1)$('#modalBody').classList.add('wide');$('.close-modal').onclick=closeModal;const single=$('#printReceipt'),all=$('#printAllReceipts');if(single)single.onclick=()=>printReceipt();if(all)all.onclick=()=>printReceipt();document.querySelectorAll('[data-print-person]').forEach(b=>b.onclick=()=>printReceipt(Number(b.dataset.printPerson)));toast(transactions.length>1?`${transactions.length} invoice split bill berhasil dibuat dan siap dicetak.`:t('success'))}
async function finalizeBillComponent(trx,items,billId=null){const key=cartKey();state.transactions.push(trx);if(state.settings.kitchenEnabled)state.tickets.unshift({id:`D-${trx.id.split('-').pop()}`,orderId:trx.orderId,table:state.orderType==='dineIn'?state.table:'TA',items:items.map(x=>`${x.qty}× ${x.name}`),status:'cooking',time:trx.time});items.forEach(x=>{const p=state.products.find(y=>y.id===x.id);if(p&&!p.unlimitedStock)p.stock=Math.max(0,p.stock-x.qty)});if(billId)state.splitBills[key]=currentSplitBills().filter(b=>b.id!==billId);else replaceCurrentCart([]);if(!currentCart().length&&!currentSplitBills().length){delete state.orderIds[key];delete state.splitPersonCounters[key];delete state.orderMeta[key]}await save();render();openModal(`${receiptHTML(trx)}<div class="modal-actions receipt-actions"><button class="secondary close-modal">${t('close')}</button><button class="primary" id="printReceipt">${t('print')}</button></div>`);$('.close-modal').onclick=closeModal;$('#printReceipt').onclick=()=>printReceipt();toast(`${trx.splitPerson?`Bill Orang ${trx.splitPerson}`:'Bill utama'} berhasil dibayar.`)}
async function completePayment(method){const cart=currentCart().map(x=>({...x})),trx=makeTransaction(cart,method);await finalizeBillComponent(trx,cart)}
async function completeSavedBillPayment(billId,method){const bill=currentSplitBills().find(b=>b.id===billId),items=bill.items.map(x=>({...x})),trx=makeTransaction(items,method,bill.personNumber);await finalizeBillComponent(trx,items,billId)}
async function completeSplitPayment(bills,methods){const original=currentCart().map(x=>({...x})),transactions=bills.map((bill,i)=>makeTransaction(bill,methods[i],i+1));await finalizeOrder(transactions,original)}
function showCategoryForm(oldName=''){openModal(`<h2>${oldName?'Edit':'Tambah'} kategori</h2><form id="categoryForm"><label class="field"><span>Nama kategori</span><input name="name" value="${esc(oldName)}" required maxlength="30" autofocus></label><div class="modal-actions"><button type="button" class="secondary close-modal">${t('close')}</button><button class="primary">Simpan kategori</button></div></form>`);$('#categoryForm').onsubmit=async e=>{e.preventDefault();const name=String(new FormData(e.target).get('name')).trim();if(!name)return;if(state.categories.some(c=>c.toLowerCase()===name.toLowerCase()&&c!==oldName)){toast('Nama kategori sudah digunakan.');return}if(oldName){state.categories[state.categories.indexOf(oldName)]=name;state.products.forEach(p=>{if(p.category===oldName)p.category=name})}else state.categories.push(name);await save();closeModal();render()}}
function deleteCategory(name){const count=state.products.filter(p=>p.category===name).length;if(count){toast(`Kategori masih digunakan oleh ${count} menu.`);return}if(!confirm(`Hapus kategori ${name}?`))return;state.categories=state.categories.filter(c=>c!==name);save();render()}
function showProductForm(id){const p=state.products.find(x=>x.id===id)||{name:'',en:'',category:state.categories[0]||'',price:'',stock:0,icon:'🍽️',active:true,taxable:true,unlimitedStock:false};openModal(`<h2>${id?'Edit':'Tambah'} menu</h2><form id="productForm" class="form-grid"><label class="field span-2"><span>Nama menu (Indonesia)</span><input name="name" value="${esc(p.name)}" required></label><label class="field span-2"><span>Nama menu (English)</span><input name="en" value="${esc(p.en)}" required></label><label class="field"><span>Kategori</span><select name="category" required>${state.categories.map(c=>`<option ${c===p.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field"><span>Ikon/emoji</span><input name="icon" value="${esc(p.icon)}" maxlength="4"></label><label class="field"><span>Harga (Rp)</span><input name="price" type="number" min="0" step="100" value="${p.price}" required></label><label class="field"><span>Stok awal</span><input name="stock" type="number" min="0" value="${p.stock}" ${p.unlimitedStock?'disabled':''} required></label><label class="check"><input name="unlimitedStock" type="checkbox" ${p.unlimitedStock?'checked':''}> Stok unlimited (∞)</label><label class="check"><input name="taxable" type="checkbox" ${p.taxable!==false?'checked':''}> Kenakan pajak 10%</label><label class="check span-2"><input name="active" type="checkbox" ${p.active!==false?'checked':''}> Tampilkan di layar kasir</label><div class="modal-actions span-2"><button type="button" class="secondary close-modal">${t('close')}</button><button class="primary">Simpan menu</button></div></form>`);const unlimited=$('#productForm [name="unlimitedStock"]'),stockInput=$('#productForm [name="stock"]');unlimited.onchange=()=>stockInput.disabled=unlimited.checked;$('#productForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),unlimitedStock=f.get('unlimitedStock')==='on',data={name:f.get('name').trim(),en:f.get('en').trim(),category:f.get('category'),icon:f.get('icon').trim()||'🍽️',price:Number(f.get('price')),stock:unlimitedStock?(p.stock||0):Number(f.get('stock')),unlimitedStock,taxable:f.get('taxable')==='on',active:f.get('active')==='on'};if(id){Object.assign(p,data);Object.values(state.carts).forEach(cart=>cart.forEach(item=>{if(item.id===id)Object.assign(item,data)}));Object.values(state.splitBills).flat().forEach(b=>b.items.forEach(item=>{if(item.id===id)Object.assign(item,data)}))}else state.products.push({id:Math.max(0,...state.products.map(x=>x.id))+1,...data});await save();closeModal();render()}}
function deleteProduct(id){const p=state.products.find(x=>x.id===id),inOrder=Object.values(state.carts).some(cart=>cart.some(x=>x.id===id))||Object.values(state.splitBills).flat().some(b=>b.items.some(x=>x.id===id));if(inOrder){toast('Menu masih ada dalam pesanan atau bill tertunda. Selesaikan pesanan terlebih dahulu.');return}if(!confirm(`Hapus menu ${p.name}?`))return;state.products=state.products.filter(x=>x.id!==id);save();render()}
function showTableForm(id=null){const table=state.tables.find(t=>t.id===id),nextNumber=Math.max(0,...state.tables.map(t=>Number(String(t.id).match(/\d+/)?.[0])||0))+1;openModal(`<h2>${table?'Ubah meja':'Tambah meja'}</h2><form id="tableForm"><label class="field"><span>ID meja</span><input name="id" value="${esc(table?.id||`M${nextNumber}`)}" required maxlength="12" ${table?'disabled':''}></label><label class="field"><span>Jumlah kursi</span><input name="seats" type="number" min="1" max="30" value="${table?.seats||4}" required></label><div class="modal-actions"><button type="button" class="secondary close-modal">${t('close')}</button><button class="primary">Simpan meja</button></div></form>`);$('#tableForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),tableId=table?.id||String(f.get('id')).trim().toUpperCase(),seats=Number(f.get('seats'));if(!table&&state.tables.some(t=>t.id.toLowerCase()===tableId.toLowerCase())){toast('ID meja sudah digunakan.');return}if(table)table.seats=seats;else state.tables.push({id:tableId,seats,status:'available'});await save();closeModal();render()}}
async function deleteTable(id){if(allOpenItems(`table:${id}`).length){toast('Meja masih memiliki pesanan atau bill tertunda.');return}if(state.tables.length===1){toast('Minimal satu meja harus tersedia.');return}if(!confirm(`Hapus meja ${id}?`))return;state.tables=state.tables.filter(t=>t.id!==id);delete state.carts[`table:${id}`];delete state.splitBills[`table:${id}`];delete state.orderIds[`table:${id}`];if(state.table===id)state.table=state.tables[0].id;await save();render()}
async function detectPrinters(){if(!window.desktop?.listPrinters){toast('Deteksi printer hanya tersedia pada aplikasi desktop.');return}availablePrinters=await window.desktop.listPrinters();renderView();toast(availablePrinters.length?`${availablePrinters.length} printer ditemukan.`:'Tidak ada printer terdeteksi.')}
async function saveOperationalSettings(form){const f=new FormData(form),printerName=f.get('printerName')||'',restaurantName=String(f.get('restaurantName')||'').trim(),receiptContentWidth=[64,68,72].includes(Number(f.get('receiptContentWidth')))?Number(f.get('receiptContentWidth')):64,receiptFontStyle=['clear','medium','bold'].includes(f.get('receiptFontStyle'))?f.get('receiptFontStyle'):'clear',directPrintMode=f.get('directPrintMode')==='graphics'?'graphics':'escpos',directPrintColumns=Number(f.get('directPrintColumns'))===48?48:42,cutFeedLines=[6,8,10].includes(Number(f.get('cutFeedLines')))?Number(f.get('cutFeedLines')):8;state.settings={...state.settings,kitchenEnabled:f.get('kitchenEnabled')==='on',printerWidth:80,receiptContentWidth,receiptFontStyle,directPrintMode,directPrintColumns,autoCut:f.get('autoCut')==='on',cutFeedLines,printerName,silentPrint:Boolean(printerName&&f.get('silentPrint')==='on'),restaurantName:restaurantName||'Restoran'};if(!state.settings.kitchenEnabled&&state.activeView==='kitchen')state.activeView='settings';await save();render();toast('Pengaturan aplikasi disimpan.')}
function showTestReceipt(){const now=new Date(),sample={id:'TEST-80MM',orderId:'ORD-TEST',time:now.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),table:'Meja Uji',waiter:'Nama Waiter',cashier:state.user.name,payment:'TEST PRINT',subtotal:150000,taxableSubtotal:100000,tax:10000,total:160000,lineItems:[{qty:1,name:'Nasi Goreng Spesial',taxable:true,lineTotal:100000},{qty:1,name:'Minuman Tanpa Pajak',taxable:false,lineTotal:50000}]};openModal(`${receiptHTML(sample)}<div class="modal-actions receipt-actions"><button class="secondary close-modal">${t('close')}</button><button class="primary" id="printReceipt">Cetak uji 80 mm</button></div>`);$('.close-modal').onclick=closeModal;$('#printReceipt').onclick=()=>printReceipt()}
async function uploadLogo(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Gunakan file logo PNG, JPG, atau WebP.');return}if(file.size>2*1024*1024){toast('Ukuran logo maksimal 2 MB.');return}const reader=new FileReader();reader.onload=async()=>{state.settings.brandLogo=reader.result;await save();render();toast('Logo restoran berhasil diganti.')};reader.onerror=()=>toast('Logo tidak dapat dibaca.');reader.readAsDataURL(file)}
async function backupDatabase(){if(!window.desktop?.backupDatabase){toast('Backup tersedia pada aplikasi desktop.');return}const result=await window.desktop.backupDatabase();if(result?.success)toast('Backup SQLite .db berhasil disimpan.');else if(!result?.canceled)toast(result?.error||'Backup database gagal.')}
async function restoreDatabase(){ if (typeof showRestoreDatabaseModal === 'function') { showRestoreDatabaseModal(); return; } if(!window.desktop?.restoreDatabase){toast('Restore tersedia pada aplikasi desktop.');return} const result=await window.desktop.restoreDatabase();if(result?.success){toast('Database berhasil dipulihkan. Aplikasi akan dimuat ulang.');setTimeout(()=>location.reload(),500)}else if(!result?.canceled)toast(result?.error||'Restore database gagal.')}

function showUserForm(id){const u=state.users.find(x=>x.id===id)||{name:'',role:'cashier',active:true};openModal(`<h2>${id?'Edit':'Tambah'} pengguna</h2><form id="userForm"><label class="field"><span>Nama pengguna</span><input name="name" value="${esc(u.name)}" required maxlength="40"></label><label class="field"><span>Peran</span><select name="role"><option value="cashier" ${u.role==='cashier'?'selected':''}>Kasir</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option><option value="owner" ${u.role==='owner'?'selected':''}>Owner</option></select></label><label class="field"><span>${id?'PIN baru (kosongkan jika tidak diubah)':'PIN 4–8 angka'}</span><input name="pin" type="password" inputmode="numeric" pattern="[0-9]{4,8}" ${id?'':'required'} autocomplete="new-password"></label><label class="check"><input name="active" type="checkbox" ${u.active?'checked':''} ${u.id===state.user.id?'disabled':''}> Pengguna aktif</label><div class="modal-actions"><button type="button" class="secondary close-modal">${t('close')}</button><button class="primary">Simpan pengguna</button></div></form>`);$('#userForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),role=f.get('role'),pin=f.get('pin'),active=u.id===state.user.id?true:f.get('active')==='on';if(u.role==='owner'&&role!=='owner'&&state.users.filter(x=>x.role==='owner'&&x.active).length===1){toast('Minimal satu owner aktif diperlukan.');return}const data={name,role,active};if(pin)data.pinHash=await hashPin(pin);if(id)Object.assign(u,data);else state.users.push({id:Math.max(0,...state.users.map(x=>x.id))+1,pinHash:await hashPin(pin),...data});if(id===state.user.id){state.user={id:u.id,name:u.name,role:u.role};if(u.role!=='owner')state.activeView='pos'}await save();closeModal();render()}}
function toggleUser(id){const u=state.users.find(x=>x.id===id);if(u.role==='owner'&&u.active&&state.users.filter(x=>x.role==='owner'&&x.active).length===1){toast('Minimal satu owner aktif diperlukan.');return}u.active=!u.active;save();render()}
function showUsers(required=false){if(required)sessionLocked=true;openModal(`<h2>Masuk sebagai pengguna</h2><p>Pilih pengguna lalu masukkan PIN.</p><div class="user-picker">${state.users.filter(u=>u.active).map(u=>`<button data-login-id="${u.id}"><strong>${esc(u.name)}</strong><span>${roleLabel(u.role)}</span></button>`).join('')}</div>${sessionLocked?'':`<div class="modal-actions"><button class="secondary close-modal">${t('close')}</button></div>`}`);document.querySelectorAll('[data-login-id]').forEach(b=>b.onclick=()=>showPinLogin(+b.dataset.loginId))}
function showPinLogin(id){
  const u=state.users.find(x=>x.id===id);
  if(!u)return;
  let currentPin='';
  const english=state.language==='en';
  openModal(`
    <div class="pin-login-container">
      <div class="pin-user-badge">
        <div class="pin-user-avatar">${esc((u.name||'U')[0].toUpperCase())}</div>
        <h2>${esc(u.name)}</h2>
        <span class="role-badge">${roleLabel(u.role)}</span>
      </div>
      <div class="pin-boxes-wrap" id="pinBoxesWrap" tabindex="0">
        <div class="pin-box" data-pin-idx="0"></div>
        <div class="pin-box" data-pin-idx="1"></div>
        <div class="pin-box" data-pin-idx="2"></div>
        <div class="pin-box" data-pin-idx="3"></div>
      </div>
      <input id="pinHiddenInput" type="password" inputmode="numeric" maxlength="8" pattern="[0-9]*" autocomplete="off" style="position:absolute;opacity:0;pointer-events:none;left:-9999px;">
      <p class="form-error" id="pinError"></p>
      <div class="pin-keypad">
        <button type="button" class="pin-key" data-key="1">1</button>
        <button type="button" class="pin-key" data-key="2">2</button>
        <button type="button" class="pin-key" data-key="3">3</button>
        <button type="button" class="pin-key" data-key="4">4</button>
        <button type="button" class="pin-key" data-key="5">5</button>
        <button type="button" class="pin-key" data-key="6">6</button>
        <button type="button" class="pin-key" data-key="7">7</button>
        <button type="button" class="pin-key" data-key="8">8</button>
        <button type="button" class="pin-key" data-key="9">9</button>
        <button type="button" class="pin-key pin-key-fn" data-key="clear" title="Clear">C</button>
        <button type="button" class="pin-key" data-key="0">0</button>
        <button type="button" class="pin-key pin-key-fn" data-key="backspace" title="Hapus">⌫</button>
      </div>
      <div class="modal-actions pin-actions">
        <button type="button" class="secondary" id="backUsers">${english?'← Back':'← Kembali'}</button>
        <button type="button" class="primary" id="submitPin">${english?'Sign in':'Masuk'}</button>
      </div>
    </div>
  `);
  const pinBoxes=document.querySelectorAll('[data-pin-idx]'),pinError=$('#pinError'),boxesWrap=$('#pinBoxesWrap'),hiddenInput=$('#pinHiddenInput');
  function updatePinBoxes(){
    pinBoxes.forEach((box,idx)=>{
      box.className='pin-box';
      if(idx<currentPin.length){box.classList.add('filled');box.innerHTML='<span class="pin-dot"></span>';}
      else{box.innerHTML='';if(idx===currentPin.length)box.classList.add('active');}
    });
    if(hiddenInput)hiddenInput.value=currentPin;
  }
  updatePinBoxes();
  async function handlePinSubmit(){
    if(!currentPin){if(pinError)pinError.textContent=english?'Enter PIN.':'Masukkan PIN.';return;}
    const hash=await hashPin(currentPin);
    if(hash!==u.pinHash){
      if(pinError)pinError.textContent=english?'Incorrect PIN. Try again.':'PIN salah. Coba kembali.';
      currentPin='';updatePinBoxes();
      if(boxesWrap){boxesWrap.classList.remove('pin-shake');void boxesWrap.offsetWidth;boxesWrap.classList.add('pin-shake');}
      return;
    }
    window.removeEventListener('keydown',onKeyDown);
    state.user={id:u.id,name:u.name,role:u.role};state.activeView='pos';sessionLocked=false;
    await save();closeModal();render();toast(english?`Signed in as ${u.name}`:`Masuk sebagai ${u.name}`);
  }
  function handleDigit(d){
    if(currentPin.length>=8)return;
    currentPin+=d;if(pinError)pinError.textContent='';updatePinBoxes();
    if(currentPin.length===4)setTimeout(()=>handlePinSubmit(),120);
  }
  function handleBackspace(){if(currentPin.length>0){currentPin=currentPin.slice(0,-1);if(pinError)pinError.textContent='';updatePinBoxes();}}
  function handleClear(){currentPin='';if(pinError)pinError.textContent='';updatePinBoxes();}
  document.querySelectorAll('.pin-key').forEach(btn=>{
    btn.onclick=e=>{
      e.preventDefault();const k=btn.dataset.key;
      if(k==='clear')handleClear();else if(k==='backspace')handleBackspace();else if(/^[0-9]$/.test(k))handleDigit(k);
    };
  });
  const onKeyDown=e=>{
    if(e.key>='0'&&e.key<='9'){e.preventDefault();handleDigit(e.key);}
    else if(e.key==='Backspace'){e.preventDefault();handleBackspace();}
    else if(e.key==='Escape'){e.preventDefault();window.removeEventListener('keydown',onKeyDown);showUsers(sessionLocked);}
    else if(e.key==='Enter'){e.preventDefault();handlePinSubmit();}
  };
  window.addEventListener('keydown',onKeyDown);
  $('#backUsers').onclick=()=>{window.removeEventListener('keydown',onKeyDown);showUsers(sessionLocked);};
  $('#submitPin').onclick=()=>handlePinSubmit();
  if(boxesWrap)boxesWrap.onclick=()=>hiddenInput?.focus();
}

function showLogoutConfirmation(){
  const english=state.language==='en';
  openModal(`
    <h2>${english?'Sign out / Log out?':'Keluar dari akun?'}</h2>
    <p>${english?`Are you sure you want to log out from <strong>${esc(state.user.name)}</strong> (${esc(roleLabel(state.user.role))})? The session will be locked and a PIN will be required to sign in.`:`Apakah Anda yakin ingin keluar dari akun <strong>${esc(state.user.name)}</strong> (${esc(roleLabel(state.user.role))})? Sesi akan dikunci dan PIN diperlukan untuk masuk kembali.`}</p>
    <div class="modal-actions">
      <button type="button" class="secondary close-modal">${english?'Cancel':'Batal'}</button>
      <button type="button" class="danger" id="confirmLogout">${english?'Log out':'Keluar Akun'}</button>
    </div>
  `);
  $('#confirmLogout').onclick=()=>{
    sessionLocked=true;
    showUsers(true);
    toast(english?'Logged out successfully.':'Berhasil keluar akun.');
  };
}

document.addEventListener('click',e=>{const nav=e.target.closest('#nav .nav-btn[data-view]');if(nav&&nav.dataset.view&&nav.dataset.view!==state.activeView){state.activeView=nav.dataset.view;render();save()}});$('#langBtn').onclick=()=>{state.language=state.language==='id'?'en':'id';render();save()};$('#openShift').onclick=()=>{state.activeView='shift';render();};$('#userBtn').onclick=()=>showUsers(false);const lb=$('#logoutBtn');if(lb)lb.onclick=()=>showLogoutConfirmation();$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};
document.addEventListener('click',async e=>{if(e.target.closest('#addTable'))showTableForm();const edit=e.target.closest('[data-table-edit]'),remove=e.target.closest('[data-table-delete]');if(edit)showTableForm(edit.dataset.tableEdit);if(remove&&!remove.disabled)deleteTable(remove.dataset.tableDelete);if(e.target.closest('#detectPrinters'))detectPrinters();if(e.target.closest('#testReceipt')){await saveOperationalSettings($('#settingsForm'));showTestReceipt()}if(e.target.closest('#collapseCart'))document.body.classList.add('cart-collapsed');if(e.target.closest('#cartReopen'))document.body.classList.remove('cart-collapsed');if(e.target.closest('#backupDatabase'))backupDatabase();if(e.target.closest('#restoreDatabase'))restoreDatabase();if(e.target.closest('#removeLogo')){state.settings.brandLogo='';await save();render();toast('Logo restoran dihapus.')}if(e.target.closest('#logoutBtn'))showLogoutConfirmation()});
document.addEventListener('change',e=>{if(e.target.name==='printerName'){const silent=$('#settingsForm [name="silentPrint"]');if(silent){silent.disabled=!e.target.value;if(!e.target.value)silent.checked=false}}if(e.target.id==='logoInput')uploadLogo(e.target.files[0]);});
document.addEventListener('submit',e=>{if(e.target.id==='settingsForm'){e.preventDefault();saveOperationalSettings(e.target)}});

load();

